parts.append('''<script>
(()=>{'use strict';const $=id=>document.getElementById(id),data=JSON.parse($('language-data').textContent),unitMap=new Map(data.units.map(u=>[u.id,u])),elements=[...document.querySelectorAll('.language-unit')],key='atlas-languages-v1';
let state={units:{},drafts:{}};const prompts={
'en-update':{task:'Escribe 80–120 palabras: resultado, bloqueo, impacto y petición concreta. Usa un caso ficticio o sin información confidencial.',guide:'Comprueba que el primer párrafo presenta el estado; luego contexto mínimo, responsable y plazo. Revisa tiempos y preposiciones. Elimina frases que no cambien la decisión del lector.'},
'en-interview':{task:'Escribe una historia real con situación, acción propia, resultado verificable y aprendizaje. No inventes métricas.',guide:'Destaca qué hiciste tú y qué hizo el equipo. Explica cómo verificaste el resultado y prepara dos preguntas de seguimiento. Usa pasado simple para hechos terminados.'},
'de-intro':{task:'Escribe 4–6 frases: nombre, procedencia, residencia, profesión e idiomas. Empieza por estructuras que puedas decir también en voz alta.',guide:'Modelos: Ich heiße Andrés. Ich komme aus Guatemala. Ich arbeite mit Daten. Ich lerne Deutsch. Comprueba verbo conjugado, mayúsculas y artículos cuando corresponda.'},
'de-room':{task:'Escribe un mensaje breve con saludo, interés por una habitación, pregunta por disponibilidad y propuesta de visita. Usa datos ficticios.',guide:'Modelo adaptable: Guten Tag, ich suche ein Zimmer. Ist das Zimmer noch frei? Kann ich am Montag kommen? Vielen Dank! Adapta sin copiar información que no entiendas.'}};
function sanitize(raw){const o={units:{},drafts:{}};if(!raw||typeof raw!=='object')return o;for(const id of unitMap.keys()){const u=raw.units?.[id];if(u&&typeof u==='object')o.units[id]={done:u.done===true,note:typeof u.note==='string'?u.note.slice(0,12000):''};}for(const p of Object.keys(prompts)){if(typeof raw.drafts?.[p]==='string')o.drafts[p]=raw.drafts[p].slice(0,20000);}return o;}
try{state=sanitize(JSON.parse(localStorage.getItem(key)||'{}'));}catch(e){}
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch(e){$('language-status').textContent='No se pudo guardar localmente. Exporta el avance para conservarlo.';}}
const norm=s=>s.normalize('NFC').toLowerCase().trim().replace(/[.!?]+$/,'').replace(/\\s+/g,' ');
const searchNorm=s=>s.normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase();
function filter(){let n=0;const q=searchNorm($('language-search').value),lang=$('language-filter').value,st=$('language-state').value;elements.forEach(el=>{const done=!!state.units[el.id]?.done;el.hidden=!!((lang&&el.dataset.language!==lang)||(q&&!searchNorm(el.textContent).includes(q))||(st==='done'&&!done)||(st==='pending'&&done));if(!el.hidden)n++;});document.querySelectorAll('.language-group').forEach(g=>g.hidden=![...g.querySelectorAll('.language-unit')].some(u=>!u.hidden));$('language-count').textContent=n+' de 20 unidades visibles';$('language-empty').hidden=n>0;}
function progress(){let total=0;for(const [lang,max] of [['en',8],['de',12]]){const n=data.units.filter(u=>u.lang===lang&&state.units[u.id]?.done).length;total+=n;$(lang+'-progress').textContent=(lang==='en'?'Inglés':'Alemán')+': '+n+' / '+max;$(lang+'-progress-bar').value=n;}$('language-progress').textContent=total+' / 20 unidades practicadas';$('language-progress-bar').value=total;}
function hydrate(){elements.forEach(el=>{el.querySelector('[data-language-done]').checked=!!state.units[el.id]?.done;el.querySelector('[data-note]').value=state.units[el.id]?.note||'';el.classList.toggle('complete',!!state.units[el.id]?.done);});progress();filter();loadDraft();}
elements.forEach(el=>{el.querySelector('[data-language-done]').addEventListener('change',e=>{state.units[el.id]={...state.units[el.id],done:e.target.checked};el.classList.toggle('complete',e.target.checked);save();progress();filter();});el.querySelector('[data-note]').addEventListener('input',e=>{state.units[el.id]={...state.units[el.id],note:e.target.value};save();});});
for(const id of ['language-search','language-filter','language-state'])$(id).addEventListener(id==='language-search'?'input':'change',filter);
document.querySelectorAll('.drill').forEach(form=>{const u=unitMap.get(form.dataset.unit),i=Number(form.dataset.check),[question,answers,why]=u.checks[i],input=form.querySelector('input'),feedback=form.querySelector('.drill-feedback');form.addEventListener('submit',e=>{e.preventDefault();const good=answers.some(a=>norm(a)===norm(input.value));feedback.textContent=(good?'Coincide con la respuesta esperada. ':'Todavía no coincide; revisa el patrón o consulta la solución. ')+why+' Esta comprobación no evalúa pronunciación ni mayúsculas.';});form.querySelector('.show-answer').addEventListener('click',()=>feedback.textContent='Respuesta: '+answers[0]+'. '+why);});
function speak(text,lang){if(!('speechSynthesis' in window)||!('SpeechSynthesisUtterance' in window)){$('speech-status').textContent='Este navegador no ofrece síntesis de voz. Usa los recursos de escucha humana.';return;}const voice=window.speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith(lang));if(!voice){$('speech-status').textContent='No hay una voz '+(lang==='de'?'alemana':'inglesa')+' disponible ahora. Usa el audio de los recursos enlazados; puedes volver a probar si el navegador carga voces.';return;}window.speechSynthesis.cancel();const utter=new SpeechSynthesisUtterance(text);utter.voice=voice;utter.lang=voice.lang;utter.rate=Number($('speech-rate').value);utter.onerror=()=>{$('speech-status').textContent='La reproducción no pudo completarse. Usa un recurso de escucha enlazado.';};window.speechSynthesis.speak(utter);$('speech-status').textContent='Voz sintética: '+voice.name+'. No evalúa tu pronunciación.';}
document.querySelectorAll('.speak').forEach(b=>b.addEventListener('click',()=>{const u=unitMap.get(b.dataset.unit);speak(u.examples[Number(b.dataset.example)][0],u.lang);}));$('speech-stop').addEventListener('click',()=>{if('speechSynthesis' in window)window.speechSynthesis.cancel();$('speech-status').textContent='Reproducción detenida.';});
let cardIndex=0;const cards=()=>data.units.filter(u=>u.lang===$('deck-language').value).flatMap(u=>u.examples.map(([phrase,meaning])=>({phrase,meaning,id:u.id,lang:u.lang})));function card(){const list=cards();cardIndex=((cardIndex%list.length)+list.length)%list.length;return list[cardIndex];}function renderCard(){const c=card(),reverse=$('deck-direction').value==='spanish';$('card-front').textContent=reverse?c.meaning:c.phrase;$('card-front').lang=reverse?'es':c.lang;$('card-back').textContent=reverse?c.phrase:c.meaning;$('card-back').lang=reverse?c.lang:'es';$('card-back').hidden=true;$('card-source').textContent=c.id+' · '+(c.lang==='de'?'Alemán':'Inglés');$('card-position').textContent='Tarjeta '+(cardIndex+1)+' / '+cards().length;}
$('card-reveal').addEventListener('click',()=>$('card-back').hidden=false);$('card-next').addEventListener('click',()=>{cardIndex++;renderCard();});$('card-speak').addEventListener('click',()=>{const c=card();speak(c.phrase,c.lang);});for(const id of ['deck-language','deck-direction'])$(id).addEventListener('change',()=>{cardIndex=0;renderCard();});
let timer=null,remaining=90,deadline=0;function showTime(){$('timer-display').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');}function stopTimer(){if(timer!==null)clearInterval(timer);timer=null;}function tick(){remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));showTime();if(remaining===0){stopTimer();$('timer-status').textContent='Tiempo terminado. Anota una mejora y repite cuando estés listo.';}}$('timer-start').addEventListener('click',()=>{if(timer!==null)return;if(remaining<=0)remaining=Number($('timer-duration').value);deadline=Date.now()+remaining*1000;timer=setInterval(tick,200);$('timer-status').textContent='Práctica en curso. El sitio no está grabando.';tick();});$('timer-pause').addEventListener('click',()=>{if(timer!==null)tick();stopTimer();$('timer-status').textContent='Temporizador en pausa.';});function resetTimer(){stopTimer();remaining=Number($('timer-duration').value);showTime();$('timer-status').textContent='Listo para otro intento. No se graba audio.';}$('timer-reset').addEventListener('click',resetTimer);$('timer-duration').addEventListener('change',resetTimer);
function countWords(){const text=$('writing-draft').value.trim();$('word-count').textContent=(text?text.split(/\\s+/u).length:0)+' palabras · guardado local';}function loadDraft(){const p=$('writing-prompt').value;$('writing-instruction').textContent=prompts[p].task;$('writing-guide').textContent=prompts[p].guide;$('writing-draft').value=state.drafts[p]||'';$('writing-draft').lang=p.startsWith('de-')?'de':'en';countWords();}$('writing-prompt').addEventListener('change',loadDraft);$('writing-draft').addEventListener('input',()=>{state.drafts[$('writing-prompt').value]=$('writing-draft').value;save();countWords();});
$('export-languages').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({program:'Atlas-Idiomas',version:1,date:new Date().toISOString(),state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='atlas-idiomas-avance.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});$('import-languages').addEventListener('click',()=>$('import-language-file').click());$('import-language-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1000000)throw Error();const raw=JSON.parse(await f.text());if(raw.program!=='Atlas-Idiomas'||raw.version!==1||!raw.state||typeof raw.state!=='object'||Array.isArray(raw.state))throw Error();const incoming=sanitize(raw.state);state={units:{...state.units,...incoming.units},drafts:{...state.drafts,...incoming.drafts}};save();hydrate();$('language-status').textContent='Avance importado. Las entradas presentes en el archivo reemplazan sus versiones locales.';}catch(err){$('language-status').textContent='Archivo inválido. Usa una exportación de Atlas Idiomas de menos de 1 MB.';}e.target.value='';});
function openHash(){const id=location.hash.slice(1);if(unitMap.has(id)||['ingles','aleman'].includes(id)){$('language-filter').value='';$('language-search').value='';$('language-state').value='';filter();if(unitMap.has(id))$(id).open=true;requestAnimationFrame(()=>$(id).scrollIntoView({block:'start'}));}}window.addEventListener('hashchange',openHash);let printState=[];window.addEventListener('beforeprint',()=>{printState=[...document.querySelectorAll('details')].map(el=>[el,el.open]);document.querySelectorAll('details').forEach(el=>el.open=true);});window.addEventListener('afterprint',()=>printState.forEach(([el,open])=>el.open=open));$('print-languages').addEventListener('click',()=>window.print());hydrate();renderCard();showTime();openHash();
})();
</script></body></html>''')
